version = file("./version").readText().trim()
plugins {
    // Apply the org.jetbrains.kotlin.jvm Plugin to add support for Kotlin.
    alias(libs.plugins.kotlin.jvm)
    id("maven-publish")

    // Apply the java-library plugin for API and implementation separation.
    `java-library`
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
    // tsm-opencv, from GitHub Packages without credentials.
    maven("https://github-package-registry-mirror.gc.nav.no/cached/maven-release")
}

dependencies {
    // Use the Kotlin Test integration.
    testImplementation("org.jetbrains.kotlin:kotlin-test")

    // Use the JUnit 5 integration.
    testImplementation(libs.junit.jupiter.engine)

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
    implementation(libs.pdfbox)
    implementation(libs.bytedeco.tesseract)
    implementation(libs.bytedeco.tesseract.platform)
    implementation(libs.tsm.opencv)

    implementation(libs.logback.classic)

    implementation(libs.jackson.module.kotlin)
}

// A jar's folders cannot be listed, so templates/index.txt lists every template file for TemplateLibrary.fromResources().
val templateIndex = tasks.register("templateIndex") {
    description = "Lists the template files in templates/index.txt"
    val templates = layout.projectDirectory.dir("src/main/resources/templates")
    val output = layout.buildDirectory.dir("generated/templateIndex")
    inputs.dir(templates)
    outputs.dir(output)
    doLast {
        val root = templates.asFile
        val files = root.walk()
            .onEnter { it == root || !it.name.startsWith(".") }
            .filter { it.isFile && !it.name.startsWith(".") }
            .map { it.relativeTo(root).invariantSeparatorsPath }
            .sorted()
            .toList()
        output.get().file("templates/index.txt").asFile.apply {
            parentFile.mkdirs()
            writeText(files.joinToString("\n", postfix = "\n"))
        }
    }
}

sourceSets {
    main {
        resources.srcDir(templateIndex)
    }
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(25)
    }
}

tasks.named("build") {
    dependsOn(templateIndex)
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
    maxHeapSize = "1g"
    systemProperty("org.bytedeco.javacpp.maxPhysicalBytes", "8G")
}

publishing {
    publications {
        create<MavenPublication>("gpr") {
            from(components["java"])
            groupId = "no.nav.tsm"
            artifactId = "sykmelding-ocr"
            version = version
        }
    }
     repositories {
         maven {
             name = "GitHubPackages"
             url = uri("https://maven.pkg.github.com/navikt/sykmelding-ocr")
             credentials {
                 username = "x-access-token"
                 password = System.getenv("GITHUB_TOKEN")
             }
         }
     }
}